<span class="line"><span style="color:#F97583;">  |</span><span style="color:#B392F0;"> jq</span><span style="color:#79B8FF;"> -r</span><span style="color:#9ECBFF;"> &#39;.[].tags[].name&#39;</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> sort</span><span style="color:#79B8FF;"> -r</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> tail</span><span style="color:#79B8FF;"> -n</span><span style="color:#9ECBFF;"> +11</span><span style="color:#E1E4E8;">)</span></span>
